export const DM_SANS_REGULAR_B64 = "";
export const DM_SANS_BOLD_B64 = "";
export const DM_SANS_ITALIC_B64 = "";
export const PLAYFAIR_BOLD_B64 = "";

export interface SystemFontsRegistration {
  hasSans: boolean;
  hasDisplay: boolean;
}

export function registerSystemPdfFonts(doc: any): SystemFontsRegistration {
  let hasSans = false;
  let hasDisplay = false;
  try {
    if (typeof doc.addFileToVFS === "function" && typeof doc.addFont === "function") {
      doc.addFileToVFS("DMSans-Regular.ttf", DM_SANS_REGULAR_B64);
      doc.addFont("DMSans-Regular.ttf", "DMSans", "normal");
      doc.addFileToVFS("DMSans-Bold.ttf", DM_SANS_BOLD_B64);
      doc.addFont("DMSans-Bold.ttf", "DMSans", "bold");
      doc.addFileToVFS("DMSans-Italic.ttf", DM_SANS_ITALIC_B64);
      doc.addFont("DMSans-Italic.ttf", "DMSans", "italic");
      hasSans = true;
      doc.addFileToVFS("PlayfairDisplay-Bold.ttf", PLAYFAIR_BOLD_B64);
      doc.addFont("PlayfairDisplay-Bold.ttf", "PlayfairDisplay", "bold");
      hasDisplay = true;
    }
  } catch (err) {
    console.warn("System PDF fonts registration warning:", err);
  }
  return { hasSans, hasDisplay };
}
